SELECT jsonb_build_object(
 'tables',(SELECT jsonb_agg(to_jsonb(t)) FROM (SELECT n.nspname AS schema,c.relname AS name,c.relkind,c.relrowsecurity,c.relforcerowsecurity,c.relacl::text FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','study_private') AND c.relkind IN ('r','p','v','S') ORDER BY 1,2) t),
 'columns',(SELECT jsonb_agg(to_jsonb(t)) FROM (SELECT table_schema,table_name,column_name,ordinal_position,data_type,udt_name,is_nullable,column_default,is_identity,identity_generation FROM information_schema.columns WHERE table_schema IN ('public','study_private') ORDER BY table_schema,table_name,ordinal_position) t),
 'constraints',(SELECT jsonb_agg(to_jsonb(t)) FROM (SELECT n.nspname AS schema,c.relname AS table_name,co.conname,co.contype,co.convalidated,pg_get_constraintdef(co.oid,true) AS definition FROM pg_constraint co JOIN pg_class c ON c.oid=co.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','study_private') ORDER BY 1,2,3) t),
 'indexes',(SELECT jsonb_agg(to_jsonb(t)) FROM (SELECT schemaname,tablename,indexname,indexdef FROM pg_indexes WHERE schemaname IN ('public','study_private') ORDER BY 1,2,3) t),
 'policies',(SELECT jsonb_agg(to_jsonb(t)) FROM (SELECT * FROM pg_policies WHERE schemaname IN ('public','study_private') OR (schemaname='storage' AND (policyname LIKE 'Think CP%' OR policyname LIKE 'Tutorial%' OR policyname LIKE 'Unused tutorial%')) ORDER BY schemaname,tablename,policyname) t),
 'functions',(SELECT jsonb_agg(to_jsonb(t)) FROM (SELECT n.nspname AS schema,p.proname AS name,pg_get_function_identity_arguments(p.oid) AS arguments,pg_get_functiondef(p.oid) AS definition,p.prosecdef,p.provolatile,p.proconfig,p.proacl::text FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN ('public','study_private') AND p.prokind='f' ORDER BY 1,2,3) t),
 'triggers',(SELECT jsonb_agg(to_jsonb(t)) FROM (SELECT n.nspname AS schema,c.relname AS table_name,t.tgname,t.tgenabled,pg_get_triggerdef(t.oid,true) AS definition FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE NOT t.tgisinternal AND (n.nspname IN ('public','study_private') OR (n.nspname='auth' AND t.tgname='think_cp_account_profile')) ORDER BY 1,2,3) t),
 'views',(SELECT jsonb_agg(to_jsonb(t)) FROM (SELECT schemaname,viewname,definition FROM pg_views WHERE schemaname IN ('public','study_private')) t)
) AS catalog;
